import {create} from 'zustand'

export const useUser = create((set, get) => ({
    data: {name: "",image: ""},
    addData: (name, image) => {
        set({data: {name, image}});
    }
}));

export const useData = create((set, get) => ({
    data: [{
        nameProject: "",
        dayCreateProject: "",
        deadlineProject: "",
        statusProject: "",
        CountTask: 0,
        Tasks: [{
            nameTask: "",
            dayCreateTask: "",
            deadlineTask: "",
            dayTargetTask: "",
            statusTask: "",
            Subtasks: [{
                nameSubtask: "",
                statusSubtask: ""
            }]
        }]
    }],
    addData: (prop) => {
        set({data: {prop}});
    }
}));
